; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: zxndotl (ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen)), starts in normal mode
; ============================================================

			OUTPUT "NTCTEST.DOT"		; the dot command (C:/DOT/NTCTEST.DOT: .ntctest at the BASIC prompt)
; ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen): NTC_ZXNDOT defined, and NTC_ZXNDOTL (the Large Model: the program from #8000, the Memory class's banks from NextZXOS's allocator - asm/ntc_lib_dot.asm)
			DEFINE NTC_ZXNDOT
			DEFINE NTC_ZXNDOTL
			org #2000

; ============================================================
; Platform start code (the platform's ntc_plat_romhead) - at the org, on to ntc_start
; ============================================================
; ------------------------------------------------------------
; The entry (the compiler puts this section first, at #2000) and the
; BASIC-side machinery: everything the ROM calls need, in one place, so
; that the Large Model (zxndotl) - which runs the program from #8000 in its
; own pages and keeps only this 8K in common with BASIC's memory - has it
; here too. Self-contained: no label from another section is named.
; ------------------------------------------------------------
dot_entry:
			di
			ld (dot_bsp), sp		; BASIC's stack: the ROM calls run on it, End returns on it
			ld (dot_hl), hl			; the arguments (0: none)
			ld (dot_bc), bc
			ld a, i
			ld (dot_iold), a		; BASIC's I (put back at the end)
			ld sp, dot_tstack		; a stack of our own for the rest of the entry
			call dot_cmdsave		; the arguments into ntc_cmdbuf before anything moves them
	IFDEF NTC_ZXNDOTL
			call dotl_setup			; the Large Model: its pages, the program read from this file
	ENDIF
			ld hl, dot_chan			; the upper screen is the channel printed to
			call dot_os
			ld a, dot_ivec >> 8		; IM 2, our handler (dot_irq) from here on, except inside dot_os
			ld i, a
			im 2
			jp ntc_start

; dot_cmdsave - (dot_hl) = the arguments: into ntc_cmdbuf, 0 ended, up to 127
; characters, up to #0D, ':' outside double quotes, or 0; leading spaces left out
dot_cmdsave:
			ld hl, (dot_hl)
			ld de, ntc_cmdbuf
			ld a, h
			or l
			jr z, dot_cs_end
			ld b, 127
			ld c, 0					; C = 1 inside quotes
dot_cs_sp:
			ld a, (hl)
			cp ' '
			jr nz, dot_cs_lp
			inc hl
			jr dot_cs_sp
dot_cs_lp:
			ld a, (hl)
			or a
			jr z, dot_cs_end
			cp #0D
			jr z, dot_cs_end
			cp '"'
			jr nz, dot_cs_nq
			ld a, c
			xor 1
			ld c, a
			ld a, '"'
dot_cs_nq:
			cp ':'
			jr nz, dot_cs_st
			bit 0, c
			jr z, dot_cs_end		; a ':' outside quotes ends the line
dot_cs_st:
			ld (de), a
			inc hl
			inc de
			djnz dot_cs_lp
dot_cs_end:
			xor a
			ld (de), a
			ret

; dot_os - HL = a routine (in this 8K) to run on BASIC's side: BASIC's stack,
; IY = ERR_NR (the ROM's), interrupts on (the ROM's keyboard scan, "scroll?"),
; and - the Large Model - BASIC's memory in slots 2-7. Back with interrupts
; off, our stack (SP as it was) and our memory; A, BC, DE, HL as the routine
; left them, IX kept. Call it on the real stack, never with SP in the thread
dot_os:
			ld (dot_osp), sp
			ld (dot_oix), ix
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack		; (the swap's calls: never on the program's stack, which is in a slot being swapped)
			push hl
			call dotl_bside			; slots 2-7 = BASIC's (ours noted)
			pop hl
	ENDIF
			ld sp, (dot_bsp)
			ld iy, #5C3A
			im 1					; the ROM's handler while the ROM runs
			ex de, hl
			ld hl, (#5C78)			; FRAMES now: its advance during the call is added to dot_frames
			ld (dot_fr0), hl
			ex de, hl
			ld de, dot_os_back
			push de
			ei
			jp (hl)
dot_os_back:
			di
			push af					; (the routine's result: A and the flags - dotl_alloc's carry)
			push hl
			push de
			ld hl, (#5C78)
			ld de, (dot_fr0)
			or a
			sbc hl, de
			ld de, (dot_frames)
			add hl, de
			ld (dot_frames), hl
			pop de
			pop hl
			pop af
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack
			push af
			push hl
			call dotl_oside			; slots 2-7 = ours again
			pop hl
			pop af
	ENDIF
			im 2
			ld sp, (dot_osp)
			ld ix, (dot_oix)
			ret

; ---- the BASIC-side routines (reached through dot_os only)
; dot_chan - the upper screen, channel 2, is the channel rst #10 prints to
dot_chan:
			ld a, 2
			rst #18
			dw #1601				; CHAN-OPEN
			ret
; dot_putc - (dot_ch) printed
dot_putc:
			ld a, (dot_ch)
			rst #10
			ret
; dot_cls - the ROM's CLS, then the channel again (CLS leaves the lower screen's)
dot_cls:
			rst #18
			dw #0D6B				; CLS
			jr dot_chan
; dot_at - AT (dot_row), (dot_col): the ROM's control code 22
dot_at:
			ld a, 22
			rst #10
			ld a, (dot_row)
			rst #10
			ld a, (dot_col)
			rst #10
			ret
; dot_wait - a frame: until the ROM's interrupt moves FRAMES on (not halt: a program
; that stops on halt can't be stepped by every harness - and the ROM's handler runs
; the same either way)
dot_wait:
			ld hl, #5C78			; FRAMES
			ld a, (hl)
dot_wt_lp:
			cp (hl)
			jr z, dot_wt_lp
			ret
; dot_kread - a frame's wait for the ROM's keyboard scan, then A = the new key
; (LAST_K, the FLAGS bit cleared) or 0
dot_kread:
			call dot_wait
			ld a, (#5C3B)			; FLAGS: bit 5 = a new key in LAST_K
			bit 5, a
			jr z, dot_kr_none
			res 5, a
			ld (#5C3B), a
			ld a, (#5C08)			; LAST_K
			ret
dot_kr_none:
			xor a
			ret

; ---- the entry's data
dot_bsp:		dw 0			; BASIC's SP at entry
dot_hl:			dw 0			; HL at entry: the arguments
dot_bc:			dw 0			; BC at entry: the whole command line
dot_osp:		dw 0			; dot_os: our SP
dot_oix:		dw 0			; dot_os: IX
dot_ch:			db 0			; the character for dot_putc
dot_row:		db 0			; dot_at: row, column (0 based)
dot_col:		db 0
dot_frames:		dw 0			; frames counted (dot_irq, plus FRAMES' advance in the ROM calls): Ticks
dot_fr0:		dw 0			; dot_os: FRAMES at the call's start
dot_iold:		db 0			; BASIC's I register
ntc_cmdbuf:		ds 128			; the arguments, 0 ended (System.CommandLine)
; dot_irq - the IM 2 handler: a frame counted. Only this 8K is touched (it runs with the
; program's memory in the slots and SP on the program's real stack)
dot_irq:
			push hl
			ld hl, (dot_frames)
			inc hl
			ld (dot_frames), hl
			pop hl
			ei
			reti
; the IM 2 vector table, 256-aligned: the Z80 reads its bytes #FF and #100 (the data bus
; gives #FF) - the handler's address; the rest is the entry's two stacks
			ALIGN 256
dot_ivec:
			ds 255 - 48
			ds 32
dot_tstack:						; the entry's own stack (32 bytes: the entry's calls only)
			ds 16
dot_xstack:						; dot_os's own (16 bytes: the slot swap's calls - the Large Model) = dot_ivec + #FF
			dw dot_irq				; the vector

	IFDEF NTC_ZXNDOTL
; ------------------------------------------------------------
; The Large Model (zxndotl): the program runs from #8000 in four 8K pages of
; its own, the Memory class's window #4000-#7FFF is two more, all allocated
; from NextZXOS (IDE_BANK through M_P3DOS) at entry and given back at the end;
; its banks (64K: 8 pages each) come from the same allocator at the Memory
; class's first call (ntc_lib_dot.asm). Slots 2-7 hold ours while the program
; runs, BASIC's while a ROM / esxDOS call runs (dot_os: dotl_bside / dotl_oside).
; The program itself is read from this file, after its first 8K (M_GETHANDLE:
; NextZXOS leaves the file open there), into #8000 on.
; ------------------------------------------------------------
DOTL_MAXPG	equ 6 + 8 * 16			; pages at most: the 6 base ones and 16 banks (1MB)
dotl_bslots:	ds 6			; BASIC's pages in slots 2-7 (NextRegs #52-#57 at entry)
dotl_oslots:	ds 6			; ours (slots 2-3 the window, 4-7 the program #8000-#FFFF), as last seen
dotl_scr:		ds 6			; (dotl_oside's reads)
dotl_npages:	db 0			; pages allocated (in dotl_pages)
dotl_pages:		ds DOTL_MAXPG	; their numbers: the 6 base ones, then the Memory class's 8 a bank
dotl_e:			db 0			; dotl_alloc: the page it got / dotl_free: the page to give back
dotl_hdl:		db 0			; this file's handle
dotl_err:		dw 0			; the message for the error return

; dotl_setup - (the entry, on dot_tstack, BASIC's memory) BASIC's slots noted, the 6
; base pages allocated and mapped, the program read into #8000 on. Doesn't return when
; it fails: the error return to BASIC with a message
dotl_setup:
			ld hl, dotl_bslots		; BASIC's pages in slots 2-7
			ld d, #52
dotl_su_rd:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)
			ld (hl), a
			inc hl
			inc d
			ld a, d
			cp #58
			jr nz, dotl_su_rd
			ld b, 6					; the 6 base pages
dotl_su_al:
			push bc
			call dotl_page			; one more into dotl_pages
			pop bc
			jr nc, dotl_su_nomem
			djnz dotl_su_al
			ld hl, dotl_pages		; ours: slots 2-3 pages 0, 1 (the window), 4-7 pages 2-5
			ld de, dotl_oslots
			ld bc, 6
			ldir
			call dotl_oside			; mapped (this 8K and the ROM stay: slots 0, 1)
			rst #08
			db #8D					; M_GETHANDLE: A = this file's handle, open after its first 8K
			ld (dotl_hdl), a
			ld hl, #8000
			ld bc, ntc_end - #8000	; the program (the file's end: no window data, no Skip on this platform)
			push bc
			rst #08
			db #9D					; F_READ: A = handle, HL = where, BC = how many
			pop hl
			jr c, dotl_su_short
			or a
			sbc hl, bc				; all of it?
			ret z
dotl_su_short:
			ld hl, dotl_m_short
			jr dotl_fail
dotl_su_nomem:
			ld hl, dotl_m_nomem
; dotl_fail - HL = the message (bit 7 on its last character): the pages back, BASIC's
; memory and stack, the esxDOS custom error return (carry set, A = 0, HL = the message)
dotl_fail:
			ld (dotl_err), hl
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld hl, (dotl_err)
			ld iy, #5C3A
			xor a
			scf
			ei
			ret
; dotl_exit - (End: ntc_plat_exit jumps here - this 8K stays mapped when slots 2-7 go
; back to BASIC's; the program's code doesn't) the pages given back, BASIC's memory and
; stack, carry clear (0 OK), interrupts on
dotl_exit:
			ld sp, dot_tstack
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld iy, #5C3A
			ld a, (dot_iold)
			ld i, a
			im 1
			or a
			ei
			ret
dotl_m_nomem:	db "Out of memory: no free 8K pages (IDE_BANK", ')' + #80
dotl_m_short:	db "The .DOT file is short: the program did not read in ful", 'l' + #80

; dotl_page - one page allocated (IDE_BANK, on BASIC's side) into dotl_pages: C = its
; number, carry set; carry clear when there is none (or no room in dotl_pages)
dotl_page:
			ld a, (dotl_npages)
			cp DOTL_MAXPG
			ret nc					; (carry clear: full)
			ld hl, dotl_alloc
			call dot_os				; carry set = got one, (dotl_e) = it
			ret nc
			ld hl, dotl_pages
			ld a, (dotl_npages)
			ld e, a
			ld d, 0
			add hl, de
			ld a, (dotl_e)
			ld (hl), a
			ld c, a
			ld a, (dotl_npages)
			inc a
			ld (dotl_npages), a
			scf
			ret
; dotl_freeall - every page in dotl_pages given back (IDE_BANK free, on BASIC's side)
dotl_freeall:
			ld a, (dotl_npages)
			or a
			ret z
			ld b, a
			ld hl, dotl_pages
dotl_fa_lp:
			ld a, (hl)
			ld (dotl_e), a
			push bc
			push hl
			ld hl, dotl_free
			call dot_os
			pop hl
			pop bc
			inc hl
			djnz dotl_fa_lp
			xor a
			ld (dotl_npages), a
			ret

; dotl_bside - slots 2-7 = BASIC's pages, ours noted first (dotl_oslots)
; dotl_oside - slots 2-7 = ours again
; (from code in this 8K, on a stack in it: slots 2-7 change under anything else)
dotl_bside:
			ld hl, dotl_oslots
			ld ix, dotl_bslots
			jr dotl_swap
dotl_oside:
			ld hl, dotl_scr
			ld ix, dotl_oslots
dotl_swap:
			ld d, #52
dotl_sw_lp:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)				; the page there now
			ld (hl), a
			ld a, (ix + 0)
			out (c), a				; the page to be
			inc hl
			inc ix
			inc d
			ld a, d
			cp #58
			jr nz, dotl_sw_lp
			ret

; ---- BASIC-side (dot_os): the allocator, M_P3DOS's IDE_BANK (#01BD): H = 0 a ZX 8K
; page, L = 1 allocate / 3 free (E = the page), the call's registers in the alternate
; set; carry SET = done, E = the page
dotl_alloc:
			ld hl, #0001
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94					; M_P3DOS
			ld a, e
			ld (dotl_e), a
			ret
dotl_free:
			ld a, (dotl_e)
			ld e, a
			ld hl, #0003
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94
			ret

; ---- esxDOS file calls for a FileSystem class (the Large Model): dot_fs_call runs on BASIC's
; side (HL = dot_fs_call : call dot_os) - NextZXOS pages its own RAM over #C000-#FFFF and reads
; BASIC's system variables during a call, so the call's stack, the name and the data must not be
; in the program's pages: the name goes in dot_fs_name, a stat buffer is dot_fs_stat, file data
; goes through dot_fs_data (256 bytes a call), all in this 8K, which is in both maps.
; In: dot_fs_hook (F_OPEN ...), dot_fs_a, dot_fs_bc, dot_fs_de, dot_fs_hl (HL and IX: NextZXOS
; reads a name's pointer from HL, esxDOS from IX). Out: dot_fs_a, dot_fs_bc, dot_fs_de,
; dot_fs_cy (1 = carry: an error, A its code)
dot_fs_call:
			ld a, (dot_fs_hook)
			ld (dot_fs_hk), a
			ld bc, (dot_fs_bc)
			ld de, (dot_fs_de)
			ld hl, (dot_fs_hl)
			push hl
			pop ix
			ld a, (dot_fs_a)
			rst #08
dot_fs_hk:	db 0
			ld (dot_fs_bc), bc
			ld (dot_fs_de), de
			ld (dot_fs_a), a
			ld a, 0
			rla
			ld (dot_fs_cy), a
			ret
dot_fs_hook:	db 0
dot_fs_a:		db 0
dot_fs_cy:		db 0
dot_fs_bc:		dw 0
dot_fs_de:		dw 0
dot_fs_hl:		dw 0
dot_fs_name:	ds 64
dot_fs_stat:	ds 16
dot_fs_data:	ds 256
	ENDIF

			ASSERT $ <= #4000, "the dot command's entry code and data must fit in #2000-#3FFF"
			ds #4000 - $			; the first 8K of the file, padded
			OPT -Wno-fileorg		; (the file goes on where the 8K ends: the org below is where the program runs, not a gap)
			org #8000			; the program: read into its own pages by the entry

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, 0		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 4: CLS
			dw kw_cls

			; 5: PRINT "NTC self test"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 6: t = 0 : bad = 0
			dw kw_ztov, var_t
			dw kw_ztov, var_bad

			; 9: got = 10 - 2 * 3 + 4 : want = 8 : GOSUB chk
			dw kw_ltov, 8, var_got
			dw kw_ltov, 8, var_want
			dw lbl_chk_gs

			; 10: got = 100 / 5 * 2 : want = 40 : GOSUB chk
			dw kw_ltov, 40, var_got
			dw kw_ltov, 40, var_want
			dw lbl_chk_gs

			; 11: got = 10 - 2 - 3 : want = 5 : GOSUB chk
			dw kw_ltov, 5, var_got
			dw kw_ltov, 5, var_want
			dw lbl_chk_gs

			; 12: got = (6 + 3) * 4 / (2 - 9) : want = -5 : GOSUB chk
			dw kw_ltov, -5, var_got
			dw kw_ltov, -5, var_want
			dw lbl_chk_gs

			; 13: got = -7 / 2 : want = -3 : GOSUB chk
			dw kw_ltov, -3, var_got
			dw kw_ltov, -3, var_want
			dw lbl_chk_gs

			; 14: got = -7 MOD 2 : want = -1 : GOSUB chk
			dw kw_ltov, -1, var_got
			dw kw_ltov, -1, var_want
			dw lbl_chk_gs

			; 15: got = 7 MOD -2 : want = 1 : GOSUB chk
			dw kw_ltov, 1, var_got
			dw kw_ltov, 1, var_want
			dw lbl_chk_gs

			; 16: a = 7 : b = -3
			dw kw_ltov, 7, var_a
			dw kw_ltov, -3, var_b

			; 17: got = a * b + a \ b : want = -23 : GOSUB chk
			dw kw_mulvv, var_a, var_b, tmp0
			dw kw_divvv, var_a, var_b, tmp1
			dw kw_add, tmp0, tmp1, var_got
			dw kw_ltov, -23, var_want
			dw lbl_chk_gs

			; 18: got = -a * -b : want = -21 : GOSUB chk
			dw kw_negv, var_a, tmp0
			dw kw_negv, var_b, tmp1
			dw kw_mulvv, tmp0, tmp1, var_got
			dw kw_ltov, -21, var_want
			dw lbl_chk_gs

			; 19: got = 32767 + 1 : want = -32768 : GOSUB chk
			dw kw_ltov, -32768, var_got
			dw kw_ltov, -32768, var_want
			dw lbl_chk_gs

			; 20: got = ABS(b) + SGN(b) : want = 2 : GOSUB chk
			dw kw_absv, var_b, tmp0
			dw kw_sgnv, var_b, tmp1
			dw kw_add, tmp0, tmp1, var_got
			dw kw_ltov, 2, var_want
			dw lbl_chk_gs

			; 23: got = (a > b) : want = -1 : GOSUB chk
			dw kw_scpgtvv, var_a, var_b
			dw kw_ftov, var_got
			dw kw_ltov, -1, var_want
			dw lbl_chk_gs

			; 24: got = (a < b) : want = 0 : GOSUB chk
			dw kw_scpltvv, var_a, var_b
			dw kw_ftov, var_got
			dw kw_ztov, var_want
			dw lbl_chk_gs

			; 25: got = (a >= 7 AND b <= -3) : want = -1 : GOSUB chk
			dw kw_scpgevl, var_a, 7
			dw kw_ftov, tmp0
			dw kw_scplevl, var_b, -3
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, var_got
			dw kw_ltov, -1, var_want
			dw lbl_chk_gs

			; 26: got = (a = 1 OR b = 1) : want = 0 : GOSUB chk
			dw kw_cpeqvl, var_a, 1
			dw kw_ftov, tmp0
			dw kw_cpeqvl, var_b, 1
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, var_got
			dw kw_ztov, var_want
			dw lbl_chk_gs

			; 27: got = NOT 0 : want = -1 : GOSUB chk
			dw kw_ltov, -1, var_got
			dw kw_ltov, -1, var_want
			dw lbl_chk_gs

			; 28: got = &HF0 AND &H3C : want = &H30 : GOSUB chk
			dw kw_ltov, 48, var_got
			dw kw_ltov, 48, var_want
			dw lbl_chk_gs

			; 29: got = 5 XOR 3 : want = 6 : GOSUB chk
			dw kw_ltov, 6, var_got
			dw kw_ltov, 6, var_want
			dw lbl_chk_gs

			; 32: s = 0 : FOR i = 1 TO 10 : s = s + i : NEXT
			dw kw_ztov, var_s
			dw kw_ltov, 1, var_i
for1_t:
			dw kw_add, var_s, var_i, var_s
			dw kw_next1l_n, var_i, 10, for1_t
for1_e:

			; 33: got = s : want = 55 : GOSUB chk
			dw kw_vtov, var_s, var_got
			dw kw_ltov, 55, var_want
			dw lbl_chk_gs

			; 34: s = 0 : FOR i = 10 TO 1 STEP -3 : s = s + i : NEXT
			dw kw_ztov, var_s
			dw kw_ltov, 10, var_i
for2_t:
			dw kw_add, var_s, var_i, var_s
			dw kw_nextdnl_n, var_i, -3, 1, for2_t
for2_e:

			; 35: got = s : want = 22 : GOSUB chk
			dw kw_vtov, var_s, var_got
			dw kw_ltov, 22, var_want
			dw lbl_chk_gs

			; 36: s = 0 : st = 2 : FOR i = 1 TO 9 STEP st : s = s + i : NEXT
			dw kw_ztov, var_s
			dw kw_ltov, 2, var_st
			dw kw_ltov, 1, var_i
			dw kw_vtov, var_st, for3_s
			dw kw_ltov, 9, for3_l
			dw kw_forentry_n, var_i, for3_s, for3_l, for3_e
for3_t:
			dw kw_add, var_s, var_i, var_s
			dw kw_fornext_n, var_i, for3_s, for3_l, for3_t
for3_e:

			; 37: got = s : want = 25 : GOSUB chk
			dw kw_vtov, var_s, var_got
			dw kw_ltov, 25, var_want
			dw lbl_chk_gs

			; 38: n = 0 : WHILE n < 7 : n = n + 1 : WEND
			dw kw_ztov, var_n
			dw wh4_c_go
wh4_t:
			dw kw_inc, var_n
wh4_c:
			dw kw_scpltvl, var_n, 7
			dw kw_goto_iftrue_n, wh4_t
wh4_e:

			; 39: got = n : want = 7 : GOSUB chk
			dw kw_vtov, var_n, var_got
			dw kw_ltov, 7, var_want
			dw lbl_chk_gs

			; 40: n = 0 : DO : n = n + 1 : IF n = 4 THEN EXIT DO
			dw kw_ztov, var_n
do5_t:
			dw kw_inc, var_n
			dw kw_cpeqvl, var_n, 4
			dw kw_goto_iffalse_n, do5_t
			dw do5_e_go
if6_1:

			; 41: LOOP
			dw do5_t_go
do5_e:

			; 42: got = n : want = 4 : GOSUB chk
			dw kw_vtov, var_n, var_got
			dw kw_ltov, 4, var_want
			dw lbl_chk_gs

			; 43: n = 10 : DO WHILE n > 0 : n = n - 3 : LOOP
			dw kw_ltov, 10, var_n
do7_t:
			dw kw_scpgtvl, var_n, 0
			dw kw_goto_iffalse_n, do7_e
			dw kw_addl, var_n, -3, var_n
			dw do7_t_go
do7_e:

			; 44: got = n : want = -2 : GOSUB chk
			dw kw_vtov, var_n, var_got
			dw kw_ltov, -2, var_want
			dw lbl_chk_gs

			; 45: s = 0
			dw kw_ztov, var_s

			; 46: FOR i = 1 TO 3 : FOR j = 1 TO 3 : s = s + i * j : NEXT j : NEXT i
			dw kw_ltov, 1, var_i
for8_t:
			dw kw_ltov, 1, var_j
for9_t:
			dw kw_mulvv, var_i, var_j, tmp1
			dw kw_add, var_s, tmp1, var_s
			dw kw_next1l_n, var_j, 3, for9_t
for9_e:
			dw kw_next1l_n, var_i, 3, for8_t
for8_e:

			; 47: got = s : want = 36 : GOSUB chk
			dw kw_vtov, var_s, var_got
			dw kw_ltov, 36, var_want
			dw lbl_chk_gs

			; 50: r = 0
			dw kw_ztov, var_r

			; 51: IF a > 5 THEN
			dw kw_scpgtvl, var_a, 5
			dw kw_goto_iffalse_n, if10_1

			; 52: IF b > 0 THEN
			dw kw_scpgtvl, var_b, 0
			dw kw_goto_iffalse_n, if11_1

			; 53: r = 1
			dw kw_ltov, 1, var_r

			; 54: ELSEIF b = -3 THEN
			dw if11_e_go
if11_1:
			dw kw_cpeqvl, var_b, -3
			dw kw_goto_iffalse_n, if11_2

			; 55: r = 2
			dw kw_ltov, 2, var_r

			; 56: ELSE
			dw if11_e_go
if11_2:

			; 57: r = 3
			dw kw_ltov, 3, var_r

			; 58: END IF
if11_e:

			; 59: END IF
if10_1:

			; 60: got = r : want = 2 : GOSUB chk
			dw kw_vtov, var_r, var_got
			dw kw_ltov, 2, var_want
			dw lbl_chk_gs

			; 61: r = 0 : IF 1 = 1 THEN IF 2 = 3 THEN r = 1 ELSE r = 2
			dw kw_ztov, var_r
			dw if13_1_go
if13_1:
			dw kw_ltov, 2, var_r
if13_e:
if12_1:

			; 62: got = r : want = 2 : GOSUB chk
			dw kw_vtov, var_r, var_got
			dw kw_ltov, 2, var_want
			dw lbl_chk_gs

			; 65: d = 0 : GOSUB lvl1
			dw kw_ztov, var_d
			dw lbl_lvl1_gs

			; 66: got = d : want = 111 : GOSUB chk
			dw kw_vtov, var_d, var_got
			dw kw_ltov, 111, var_want
			dw lbl_chk_gs

			; 70: FOR i = 0 TO 10 : arr(i) = i * i : NEXT
			dw kw_ztov, var_i
for14_t:
			dw kw_mulvv, var_i, var_i, tmp1
			dw kw_aset, arr_arr, var_i, tmp1
			dw kw_next1l_n, var_i, 10, for14_t
for14_e:

			; 71: s = 0 : FOR i = 0 TO 10 : s = s + arr(i) : NEXT
			dw kw_ztov, var_s
			dw kw_ztov, var_i
for15_t:
			dw kw_aget, arr_arr, var_i, tmp1
			dw kw_add, var_s, tmp1, var_s
			dw kw_next1l_n, var_i, 10, for15_t
for15_e:

			; 72: got = s : want = 385 : GOSUB chk
			dw kw_vtov, var_s, var_got
			dw kw_ltov, 385, var_want
			dw lbl_chk_gs

			; 73: got = arr(3) + arr(a) : want = 58 : GOSUB chk
			dw kw_aget, arr_arr, var_a, tmp1
			dw kw_add, arr_arr+6, tmp1, var_got
			dw kw_ltov, 58, var_want
			dw lbl_chk_gs

			; 76: POKE &H8000, 200 : DOKE &H8002, -1234
			dw kw_ltolptr8, 200, -32768
			dw kw_ltolptr, -1234, -32766

			; 77: got = PEEK(&H8000) : want = 200 : GOSUB chk
			dw kw_lptrtov8, -32768, var_got
			dw kw_ltov, 200, var_want
			dw lbl_chk_gs

			; 78: addr = &H8002 : got = DEEK(addr) : want = -1234 : GOSUB chk
			dw kw_ltov, -32766, var_addr
			dw kw_vptrtov, var_addr, var_got
			dw kw_ltov, -1234, var_want
			dw lbl_chk_gs

			; 81: x$ = "abc" : y$ = x$ + "def" + x$
			dw kw_strcpy, var_x, str1
			dw kw_strcpy, stmp0, var_x
			dw kw_strcat, stmp0, str2
			dw kw_strcpy, var_y, stmp0
			dw kw_strcat, var_y, var_x

			; 82: got = LEN(y$) : want = 9 : GOSUB chk
			dw kw_strlen, var_y, var_got
			dw kw_ltov, 9, var_want
			dw lbl_chk_gs

			; 83: got = 0 : IF y$ = "abcdefabc" THEN got = 1
			dw kw_ztov, var_got
			dw kw_strcmpeq, var_y, str3
			dw kw_goto_iffalse_n, if16_1
			dw kw_ltov, 1, var_got
if16_1:

			; 84: want = 1 : GOSUB chk
			dw kw_ltov, 1, var_want
			dw lbl_chk_gs

			; 85: got = 0 : IF x$ <> y$ THEN got = 1
			dw kw_ztov, var_got
			dw kw_strcmpne, var_x, var_y
			dw kw_goto_iffalse_n, if17_1
			dw kw_ltov, 1, var_got
if17_1:

			; 86: want = 1 : GOSUB chk
			dw kw_ltov, 1, var_want
			dw lbl_chk_gs

			; 89: RANDOMIZE 99 : ok = 1
			dw kw_seedl, 99
			dw kw_ltov, 1, var_ok

			; 90: FOR i = 1 TO 100 : r = RND(6) : IF r < 0 OR r > 5 THEN ok = 0
			dw kw_ltov, 1, var_i
for18_t:
			dw kw_rndl, 6, var_r
			dw kw_scpltvl, var_r, 0
			dw kw_ftov, tmp0
			dw kw_scpgtvl, var_r, 5
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if19_1
			dw kw_ztov, var_ok
if19_1:

			; 91: NEXT
			dw kw_next1l_n, var_i, 100, for18_t
for18_e:

			; 92: got = ok : want = 1 : GOSUB chk
			dw kw_vtov, var_ok, var_got
			dw kw_ltov, 1, var_want
			dw lbl_chk_gs

			; 94: PRINT
			dw kw_printnl

			; 95: PRINT t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str4
			dw kw_printint, var_bad
			dw kw_printstrvar, str5
			dw kw_printnl

			; 98: PRINT "-12345 = "; -12345
			dw kw_printstrvar, str6
			dw kw_printnl

			; 99: INPUT "Type your name"; nm$
			dw kw_printstrvar, str7
			dw kw_inputstr, var_nm

			; 100: PRINT "Hello "; nm$; "!"
			dw kw_printstrvar, str8
			dw kw_printstrvar, var_nm
			dw kw_printstrvar, str9
			dw kw_printnl

			; 101: INPUT "Number"; v
			dw kw_printstrvar, str10
			dw kw_inputint, var_v

			; 102: PRINT v; " * 3 = "; v * 3
			dw kw_printint, var_v
			dw kw_mulvl, var_v, 3, tmp0
			dw kw_printstrvar, str11
			dw kw_printint, tmp0
			dw kw_printnl

			; 103: PRINT "Press a key";
			dw kw_printstrvar, str12

			; 104: DO : k = INKEY : FRAME : LOOP UNTIL k <> 0
do20_t:
			dw kw_inkey, tmp0
			dw kw_vtov, tmp0, var_k
			dw kw_frame
			dw kw_cpnevl, var_k, 0
			dw kw_goto_iffalse_n, do20_t
do20_e:

			; 105: PRINT " - code "; k
			dw kw_printstrvar, str13
			dw kw_printint, var_k
			dw kw_printnl

			; 106: LOCATE 25, 25 : PRINT "bottom line";
			dw kw_locatell, 25, 25
			dw kw_printstrvar, str14

			; 107: END
			dw kw_printnl0
			dw kw_printstrvar, str12
			dw kw_waitkey
			dw kw_stop

			; 109: chk:
lbl_chk:

			; 110: t = t + 1
			dw kw_inc, var_t

			; 111: PRINT t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str15

			; 112: IF got = want THEN PRINT "ok "; ELSE PRINT "FAIL "; : bad = bad + 1
			dw kw_cpeqvv, var_got, var_want
			dw kw_goto_iffalse_n, if21_1
			dw kw_printstrvar, str16
			dw if21_e_go
if21_1:
			dw kw_printstrvar, str17
			dw kw_inc, var_bad
if21_e:

			; 113: RETURN
			dw lbl_chk_rt

			; 115: lvl1: d = d + 1 : GOSUB lvl2 : RETURN
lbl_lvl1:
			dw kw_inc, var_d
			dw lbl_lvl2_gs
			dw lbl_lvl1_rt

			; 116: lvl2: d = d + 10 : GOSUB lvl3 : RETURN
lbl_lvl2:
			dw kw_addl, var_d, 10, var_d
			dw lbl_lvl3_gs
			dw lbl_lvl2_rt

			; 117: lvl3: d = d + 100 : RETURN
lbl_lvl3:
			dw kw_addl, var_d, 100, var_d
			dw lbl_lvl3_rt

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

wh4_c_go:			ld sp, wh4_c
			jp ntc_xn
do5_e_go:			ld sp, do5_e
			jp ntc_xn
do5_t_go:			ld sp, do5_t
			jp ntc_xn
do7_t_go:			ld sp, do7_t
			jp ntc_xn
if11_e_go:			ld sp, if11_e
			jp ntc_xn
if13_1_go:			ld sp, if13_1
			jp ntc_xn
if21_e_go:			ld sp, if21_e
			jp ntc_xn
lbl_chk_gs:			ld (lbl_chk_rs), sp
			ld sp, lbl_chk
			jp ntc_xn
lbl_chk_rt:			ld sp, (lbl_chk_rs)
			jp ntc_xn
lbl_lvl1_gs:			ld (lbl_lvl1_rs), sp
			ld sp, lbl_lvl1
			jp ntc_xn
lbl_lvl1_rt:			ld sp, (lbl_lvl1_rs)
			jp ntc_xn
lbl_lvl2_gs:			ld (lbl_lvl2_rs), sp
			ld sp, lbl_lvl2
			jp ntc_xn
lbl_lvl2_rt:			ld sp, (lbl_lvl2_rs)
			jp ntc_xn
lbl_lvl3_gs:			ld (lbl_lvl3_rs), sp
			ld sp, lbl_lvl3
			jp ntc_xn
lbl_lvl3_rt:			ld sp, (lbl_lvl3_rs)
			jp ntc_xn

