; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## kw_lptrtov8
;kw_lptrtov8, <literaladdr>, <destvar>  - PEEK(literal)
kw_lptrtov8:
			pop hl
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_vptrtov
;kw_vptrtov, <addrvar>, <destvar>  - DEEK(var)
kw_vptrtov:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ex de, hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_ltolptr8
;kw_ltolptr8, <literal>, <literaladdr>  - POKE literal, literal
kw_ltolptr8:
			pop bc
			pop hl
			ld (hl), c
			ret

;## kw_ltolptr
;kw_ltolptr, <literal>, <literaladdr>  - DOKE literal, literal
kw_ltolptr:
			pop bc
			pop hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## ntc_rnd_seed
ntc_rnd_seed:	dw 1

;## kw_rndl ntc_rnd_seed ntc_div
;kw_rndl, <literal>, <destvar>
kw_rndl:
			pop de
ntc_rnd:
			ld hl, (ntc_rnd_seed)
			ld a, h
			rra
			ld a, l
			rra
			xor h
			ld h, a
			ld a, l
			rra
			ld a, h
			rra
			xor l
			ld l, a
			xor h
			ld h, a
			ld (ntc_rnd_seed), hl
			bit 7, d
			jr nz, ntc_rnd_zero
			ld a, d
			or e
			jr z, ntc_rnd_zero
			ld a, 1
			ld (ntc_mode), a
			res 7, h
			jp ntc_div
ntc_rnd_zero:
			ld hl, 0
			jp ntc_div_store

;## kw_seedl ntc_rnd_seed
;kw_seedl, <literal>
kw_seedl:
			pop hl
ntc_seed:
			ld a, h
			or l
			jr nz, ntc_seed_ok
			inc l
ntc_seed_ok:
			ld (ntc_rnd_seed), hl
			ret

; ============================================================
; Strings: 0 terminated. A string variable or temp has its capacity
; (1 .. 255 chars) in the byte before it: [cap][text...][0]. Array
; elements have no capacity byte (the caller gives the element size).
; Functions that build a string write into a temp, so they cut at
; NTC_STRMAX (the longest string in the program, set by the compiler);
; kw_strcpy / kw_strcat / input cut at the destination's capacity.
; ============================================================

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			pop hl
			ld bc, 0
ntc_strlen_loop:
			ld a, (hl)
			or a
			jr z, ntc_strlen_done
			inc hl
			inc c
			jr ntc_strlen_loop
ntc_strlen_done:
			pop hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## kw_strcmpne
;kw_strcmpne, <addr1>, <addr2>  - Z if not equal
kw_strcmpne:
			pop de
			pop hl
ntc_strne_loop:
			ld a, (de)
			cp (hl)
			jr nz, ntc_strne_t
			or a
			jr z, ntc_strne_f
			inc hl
			inc de
			jr ntc_strne_loop
ntc_strne_t:
			xor a
			ret
ntc_strne_f:
			inc a
			ret

; ============================================================
; I/O - no firmware, no call, no push. SP stays in the thread.
; Shared routines are entered with jp and the return address in
; IX, and end with jp (ix). Keywords that are done use
; ld ix, ntc_next (a ret) so the routine continues the thread.
; ============================================================

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_gets ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and DEL (or backspace). HL = buffer (its capacity in the byte
; before it), DE = where to
; jp when done (after the newline). 40 chars max, 0 terminated.
ntc_gets:
			ld (ntc_iptr), hl
			ld (ntc_ilink), de
			dec hl
			ld a, (hl)			; the buffer's capacity
			ld (ntc_icap), a
			xor a
			ld (ntc_icnt), a
ntc_gs_wait:
			ld ix, ntc_gs_key
			jp ntc_plat_getkey
ntc_gs_key:
			cp 13
			jr z, ntc_gs_done
			cp 127
			jr z, ntc_gs_del
			cp 8
			jr z, ntc_gs_del
			cp 32
			jr c, ntc_gs_wait
			ld c, a
			ld a, (ntc_icap)
			ld b, a
			ld a, (ntc_icnt)
			cp b
			jr nc, ntc_gs_wait
			inc a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			ld (hl), c
			inc hl
			ld (ntc_iptr), hl
			ld a, c
			ld ix, ntc_gs_wait
			jp ntc_plat_putc
ntc_gs_del:
			ld a, (ntc_icnt)
			or a
			jr z, ntc_gs_wait
			dec a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			dec hl
			ld (ntc_iptr), hl
			ld ix, ntc_gs_wait
			jp ntc_plat_backspace
ntc_gs_done:
			ld hl, (ntc_iptr)
			ld (hl), 0
			ld ix, (ntc_ilink)
			jp ntc_plat_newline

;## kw_inputstr ntc_gets
;kw_inputstr, <straddr>
kw_inputstr:
			pop hl
			ld de, ntc_next
			jp ntc_gets

;## kw_inputint ntc_gets ntc_atoi
;kw_inputint, <var>  - signed decimal, stops at the first non digit
kw_inputint:
			pop hl
			ld (ntc_ivar), hl
			ld hl, ntc_inbuf
			ld de, ntc_atoi
			jp ntc_gets

;## ntc_atoi ntc_data
; text to number into the var at (ntc_ivar). ntc_atoi reads ntc_inbuf,
; ntc_atoi_hl reads HL. Spaces first, then - , then digits (or &H hex).
ntc_atoi:
			ld hl, ntc_inbuf
ntc_atoi_hl:
			ld a, (hl)
			cp ' '
			jr nz, ntc_atoi_sign
			inc hl
			jr ntc_atoi_hl
ntc_atoi_sign:
			ld c, 0
			cp '-'
			jr nz, ntc_atoi_amp
			inc c
			inc hl
			ld a, (hl)
ntc_atoi_amp:
			ld de, 0
			cp '&'
			jr nz, ntc_atoi_loop
			inc hl
			ld a, (hl)
			or #20
			cp 'h'
			jr nz, ntc_atoi_done
			inc hl
ntc_atoi_hex:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr c, ntc_atoi_hd
			or #20
			sub 'a' - '0'
			jr c, ntc_atoi_done
			cp 6
			jr nc, ntc_atoi_done
			add a, 10
ntc_atoi_hd:
			ex de, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			or l
			ld l, a
			ex de, hl
			inc hl
			jr ntc_atoi_hex
ntc_atoi_loop:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr nc, ntc_atoi_done
			ld (ntc_aptr), hl
			ex de, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de
			add hl, hl
			ld e, a
			ld d, 0
			add hl, de
			ex de, hl
			ld hl, (ntc_aptr)
			inc hl
			jr ntc_atoi_loop
ntc_atoi_done:
			ld a, c
			or a
			jr z, ntc_atoi_store
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_atoi_store:
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_inkey_got
			jp ntc_plat_scankey
ntc_inkey_got:
			ld hl, (ntc_ivar)
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## kw_cls ntc_data ntc_plat_screen
;kw_cls
kw_cls:
			ld ix, ntc_next
			jp ntc_plat_cls

;## kw_locatell ntc_data ntc_plat_screen
;kw_locatell, <x>, <y>  - 1 based
kw_locatell:
			pop bc
			pop de
			ld h, c
			ld l, e
			ld ix, ntc_next
			jp ntc_plat_locate

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

;## ntc_plat_exit
; ntc_plat_exit - back to BASIC: the pages given back, its memory in slots 2-7, its
; stack, carry clear (0 OK), interrupts on - dotl_exit, in the entry's 8K
ntc_plat_exit:
			jp dotl_exit			; (in the entry's 8K: the program's own pages are unmapped on the way)

;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not use:
; #FF80, under the real stack (128 bytes from #FFFF down). Called on the real stack
; (call / ret), only by the Memory class
ntc_plat_memtop:
			ld hl, #FF80
			ret

; ============================================================
; NTC Platform - ZX Spectrum Next, a dot command: the Small Model
; (c) 2026 Cyborg Unicorn Pty Ltd - MIT License
; ============================================================
; No call, no push: SP stays in the thread. Every routine is
; entered with jp, return address in IX, and ends with jp (ix).
;
; A NextZXOS / esxDOS dot command: NAME.DOT in C:/DOT, typed as .name args
; at the BASIC prompt. NextZXOS loads the file at #2000 into DivMMC's 8K
; page and calls it with HL = the arguments (0: none), BC = the whole line,
; SP = BASIC's stack; it returns with ret, carry clear (0 OK), or carry set
; and A = an esxDOS error, or A = 0 and HL = its own message (bit 7 on the
; last character). The BASIC program, its variables and its screen are kept
; as found: this is a utility that runs and comes back, not a program that
; owns the machine (that is the zxn platform: a NEX file).
;
; Memory  the 8K at #2000-#3FFF, and nothing else: the code, its data, the
;         arrays (ntc_free must end by #4000: the assembly says so when not),
;         the real stack (dot_stack, 128 bytes in the data). Option Memory
;         Small: the heap is what is left up to #4000 (ntc_plat_memtop). The
;         Large Model (zxndotl, built on this one) has 32K and banks.
;           #0000-#1FFF  DivMMC's ROM (esxDOS: rst 8 the file calls, rst #10 /
;                        rst #18 the 48K ROM's print and routines)
;           #2000-#3FFF  this dot command
;           #4000-#FFFF  BASIC's: the screen, the system variables, its
;                        program and stack - not touched
; Console text goes to BASIC's screen through the 48K ROM's rst #10 (the
;         current channel: the upper screen, opened at the start), so it
;         prints as every dot command does - in the mode BASIC is in, scrolling,
;         "scroll?" and all. Cls is the ROM's CLS, Locate the AT control code
;         (22, row, column), Mode does nothing. 32 columns, 24 rows are
;         counted (the ROM wraps and scrolls itself). Keys come from the ROM's
;         keyboard scan (LAST_K, set by its interrupt): Enter 13, Delete 127,
;         the cursor keys the CPC firmware's codes (up 240, down 241, left 242,
;         right 243), as the zxn platform gives them.
; The ROM  (the sections that switch to the real stack for dot_os are @shared: one
;         copy, no normal mode rewrite of their SP loads - as cpm's ntc_bdos)
;         a ROM routine (rst #10, rst #18, M_P3DOS) pages DivMMC out while
;         it runs, so this 8K is not there then: such a call runs on BASIC's
;         stack (SP as the command was entered) through dot_os, with IY the
;         ROM's (ERR_NR, #5C3A), IM 1 and interrupts on for the ROM's keyboard
;         and "scroll?".
; Interrupts  while the program runs the Z80 is in IM 2 with a vector and a
;         handler of its own in this 8K (dot_irq: it counts dot_frames), so the
;         ROM's handler at #0038 - which would page DivMMC out under a stack in
;         this 8K, or run over nothing of BASIC's with the Large Model's pages in
;         the slots - never runs then. Normal mode's safe points let interrupts in
;         as on every platform (the handler only touches this 8K). The vector
;         table is 257 bytes of which only the last two are read (the data bus
;         gives #FF): the rest holds the entry's two small stacks.
; Frame   waits for the next interrupt (dot_frames moving on); Ticks is
;         dot_frames: the frames counted here, plus FRAMES' advance during the
;         ROM calls (dot_os adds it), 50 a second.
; Command line  System.CommandLine: the arguments, copied at entry into
;         ntc_cmdbuf (up to 127 characters), ended at #0D, ':' (outside
;         quotes) or 0 - before anything can move BASIC's line.
; End     ntc_plat_exit: SP back, carry clear, ei, ret - the BASIC prompt
;         prints 0 OK and the program is as it was.
; Files   none yet (the FileSystem class is not on this platform; esxDOS's
;         F_OPEN / F_READ ... through rst 8 are the way, later).
; ============================================================
;@text     byte
;@scrinit  0
;@irq      0
;@cols     32
;@rows     24
;@dotfile  1
; ============================================================

;## ntc_plat_data
ntc_curx:		db 0			; column (0 based) - counted for Tab
ntc_cury:		db 0			; row (0 based)
ntc_scols:		db 32			; columns
ntc_smode:		db 1			; screen mode (nothing here: 32 columns)
			ds 128
dot_stack:						; the program's real stack (;@stack): 128 bytes, in the 8K

;## ntc_plat_screen ntc_plat_data ntc_data @shared
; ntc_plat_putc - A = character: rst #10 on BASIC's side, the column counted (the
; ROM wraps at the edge: so does the count)
ntc_plat_putc:
			ld (dot_ch), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			cp b
			jr c, ntc_pc_col
			xor a					; wrapped: the ROM moved to the next row
			ld hl, ntc_cury
			inc (hl)
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - 13 (the ROM's new line)
ntc_plat_newline:
			ld a, 13
			ld (dot_ch), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 24
			jr c, ntc_nl_row
			ld a, 23				; (the ROM scrolls)
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_backspace @unit ntc_plat_screen ntc_plat_data ntc_data @shared
; ntc_plat_backspace - 8 (back one), space, 8 (only on the current line)
ntc_plat_backspace:
			ld a, (ntc_curx)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_curx), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld a, 8
			ld (dot_ch), a
			ld hl, dot_putc
			call dot_os
			ld a, ' '
			ld (dot_ch), a
			ld hl, dot_putc
			call dot_os
			ld a, 8
			ld (dot_ch), a
			ld hl, dot_putc
			call dot_os
			ld sp, (ntc_ip)
ntc_bs_none:
			jp (ix)

;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data @shared
; ntc_plat_cls - the ROM's CLS
ntc_plat_cls:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_cls
			call dot_os
			ld sp, (ntc_ip)
			xor a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_locate @unit ntc_plat_screen ntc_plat_data ntc_data @shared
; ntc_plat_locate - H = column, L = row (1 based): AT row - 1, column - 1 (the ROM's
; AT takes rows 0-21: 23 and 24 are the lower screen's, left to the ROM)
ntc_plat_locate:
			ld a, h
			dec a
			ld (ntc_curx), a
			ld (dot_col), a
			ld a, l
			dec a
			cp 22					; (past BASIC's screen the ROM's AT stops the command with an error: row 22 is
			jr c, ntc_lc_row		; the last. Columns are left to the ROM - BASIC may be in a wider mode)
			ld a, 21
ntc_lc_row:
			ld (ntc_cury), a
			ld (dot_row), a
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_at
			call dot_os
			ld sp, (ntc_ip)
			jp (ix)

;## ntc_plat_key ntc_data @shared
; ntc_plat_scankey - A = key or 0: the ROM's LAST_K after a frame (its interrupt
; scans the keyboard), the ROM's codes made the platform's: Enter 13, Delete (12)
; 127, the cursor keys (8-11) 242, 243, 241, 240; other control codes 0
ntc_plat_scankey:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_kread
			call dot_os
			ld sp, (ntc_ip)
			cp 32
			jr nc, ntc_sk_done		; a character
			cp 13
			jr z, ntc_sk_done
			cp 12
			jr nz, ntc_sk_cur
			ld a, 127				; Delete
			jr ntc_sk_done
ntc_sk_cur:
			cp 8
			jr c, ntc_sk_none
			cp 12
			jr nc, ntc_sk_none
			ld hl, ntc_sk_tab - 8
			add a, l
			ld l, a
			jr nc, ntc_sk_rd
			inc h
ntc_sk_rd:
			ld a, (hl)
			jr ntc_sk_done
ntc_sk_none:
			xor a
ntc_sk_done:
			jp (ix)
ntc_sk_tab:		db 242, 243, 241, 240	; left, right, down, up

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			ld (ntc_gklink), ix
ntc_gk_poll:
			ld ix, ntc_gk_back
			jp ntc_plat_scankey
ntc_gk_back:
			or a
			jr z, ntc_gk_poll
			ld ix, (ntc_gklink)
			jp (ix)
ntc_gklink:		dw 0

;## ntc_plat_frame ntc_data @shared
; ntc_plat_frame - a frame: the next interrupt (dot_irq counts it), interrupts let in
; for it on the real stack
ntc_plat_frame:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ld hl, dot_frames
			ld a, (hl)
			ei
ntc_fr_lp:
			cp (hl)
			jr z, ntc_fr_lp
			di
			ld sp, (ntc_ip)
			jp (ix)


ntc_end:				; the end of the program (and of its file)
			DISPLAY "NTC memory: program ", /H, ntc_start, "-", /H, ntc_end - 1, " arrays ", /H, ntc_bss, "-", /H, ntc_free - 1, " stack 0 down (the platform's)"
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_arr		equ ntc_bss + 0		; 22 bytes
ntc_bss_size	equ 22
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			ASSERT ntc_free <= #FF80, "zxndotl: the program and its arrays must end by #FF80 (the 32K at #8000, less the stack)"
